if(B.e.j(r,"chartreuse"))return"\ud83c\udf3f"
if(B.e.j(r,"whisky")||B.e.j(r,"bourbon"))return"\ud83e\udd43"
if(B.e.j(r,"rhum")||B.e.j(r,"rum"))return"\ud83c\udff4\u200d\u2620\ufe0f"
